"""Bridge archive graph faults, funded bus protection, closure, repair and salvage."""
import hashlib,json
from playwright.sync_api import sync_playwright
from test_mobile_rendering import ROOT,html
source=(ROOT/'assets/game.js').read_text()
probe=r'''window.__bridgeStates={setup:()=>{__townTest.reset('settlement',42);G.autoBuild=false;const p=ANNEX_PARCELS.find(p=>p.id==='east-meadow');if(!purchaseParcel(p.id,parcelSurvey(p).price))throw Error('Deed failed');for(let x=43;x<=63;x++)construct('road',x,15,true);for(let x=69;x<=76;x++)construct('road',x,15,true);flushRoadBatch();invalidateRoads();const bank=roadId(63,15),q=bridgeCandidateFromBank(bank);if(!q.ok||!commitRoadBridge(bank,q.key).ok)throw Error('Bridge failed');return G.bridges[0].id;},
 archive:()=>{if(!hydrateSave(archivePayload()))throw Error('Valid bridge rejected');const raw=archivePayload(),faults={missingBridge:g=>{delete g.bridges},orphanDeck:g=>g.tiles[g.bridges[0].cells[0]]=2,duplicateCell:g=>g.bridges[0].cells[1]=g.bridges[0].cells[0],duplicateIdentity:g=>g.bridges.push({...g.bridges[0]}),badBank:g=>g.bridges[0].banks[0]++,badAxis:g=>g.bridges[0].axis='diagonal',badCondition:g=>g.bridges[0].condition=-1,futureBuild:g=>g.bridges[0].builtDay=g.day+1,unfundedCapital:g=>g.bridges[0].capital=0,missingDeed:g=>{g.charter.owned=[];g.charter.deeds=[];g.charter.revision=0;}};const rows=[];for(const [name,fault]of Object.entries(faults)){const bad=JSON.parse(raw);fault(bad);const before=archivePayload(),caller=JSON.stringify(bad),rng=rngState,head=JSON.stringify([saveEpoch,saveTown,saveRevision,saveOrder]);if(hydrateSave(bad)||archivePayload()!==before||rngState!==rng||JSON.stringify(bad)!==caller||head!==JSON.stringify([saveEpoch,saveTown,saveRevision,saveOrder]))throw Error('Bridge archive rejection not atomic: '+name);rows.push(name)}return rows;},
 fishery:()=>{window.__bridgeStates.setup();const b=G.bridges[0],cells=new Set(b.cells),bank=b.banks[0],remove=bridgeRemovalQuote(b.id);if(!decommissionBridge(b.id,remove.key).ok)throw Error('Clear fixture deck failed');const q=bridgeCandidateFromBank(bank),total=totalMoney();let spot=null;for(let y=8;y<30&&!spot;y++)for(let x=56;x<77;x++){if(!canPlace(x,y,true,'fishery'))continue;const site=waterfrontSite(x,y,'fishery');if(site&&fishingRoute(site).some(id=>cells.has(id))){spot={x,y};break}}if(!spot)throw Error('No real fishery shore reaches span');const count=G.firms.length;construct('fishery',spot.x,spot.y,true);if(G.firms.length!==count+1||G.firms.at(-1).kind!=='fishery')throw Error('Fishery construction failed');const denied=bridgeCandidateFromBank(bank);return {shore:spot,planningDenied:!denied.ok,treasurySufficient:G.treasury>=q.cost,moneyConserved:Math.abs(totalMoney()-total)<.001,reason:denied.reason};},
 bus:()=>{const spot=buildableCandidates('business').find(p=>canPlace(p.x,p.y,true,'transit_depot')),depot=spot&&buildTransitFacility('transit_depot',spot.x,spot.y);if(!depot)throw Error('Depot failed');const spec={mode:'bus',depot:depot.id,stops:[roadId(63,15),roadId(69,15),roadId(76,15)],level:1},q=transitQuote(spec),route=q.ok&&buildTransitRoute(spec,q);if(!route)throw Error('Funded bus failed: '+q.reason);const b=G.bridges[0],usesAll=b.cells.every(id=>route.path.includes(id)),before=archivePayload(),quote=bridgeRemovalQuote(b.id);if(quote.ok||!usesAll||archivePayload()!==before)throw Error('Active bus not protected');if(!deleteTransitRoute(route.id))throw Error('Route retirement failed');return {usesAll,reason:quote.reason,retiredRouteUnlocksDecommission:bridgeRemovalQuote(b.id).ok};},
 close:()=>{const b=G.bridges[0];b.condition=25.1;G.bridgeRevision++;invalidateRoads(false);G.region+=G.treasury;G.treasury=0;const total=totalMoney();maintainRoadBridges();return {condition:b.condition,closed:!roadSurface(b.cells[0]),roadDisconnected:graph().parts[b.banks[0]]!==graph().parts[b.banks[1]],waterIntact:b.cells.every(id=>waterNetwork().components.some(c=>c.cells.includes(id))),moneyConserved:Math.abs(totalMoney()-total)<.001,paid:G.bridgeMaintenancePaid};},
 fund:()=>{const amount=20000-G.treasury;G.region-=amount;G.treasury+=amount;return {cash:G.treasury,total:totalMoney(),repair:bridgeRepairQuote(G.bridges[0].id).cost};},state:()=>({cash:G.treasury,total:totalMoney(),bridges:G.bridges.length,cells:[1984,1985,1986,1987,1988].map(id=>G.tiles[id]),open:G.bridges.length&&roadSurface(G.bridges[0].cells[0]),condition:G.bridges[0]?.condition,valid:validateTown().ok,quote:G.bridges.length&&bridgeRemovalQuote(G.bridges[0].id)})};'''
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page(viewport={'width':844,'height':390});p.set_content(html);p.add_script_tag(content=source.replace('// SOURCE: 99-instrumentation.js',probe+'\n// SOURCE: 99-instrumentation.js'));p.locator('#newTown').click();p.locator('#pause').click();identity=p.evaluate('__bridgeStates.setup()');faults=p.evaluate('__bridgeStates.archive()');bus=p.evaluate('__bridgeStates.bus()');assert bus['retiredRouteUnlocksDecommission'],bus
 closed=p.evaluate('__bridgeStates.close()');assert all(closed[k] for k in ['closed','roadDisconnected','waterIntact','moneyConserved']) and closed['paid']==0,closed
 funded=p.evaluate('__bridgeStates.fund()');p.locator('[data-panel=construction]').click();repair=p.locator('[data-bridge-repair]');repair.scroll_into_view_if_needed();repair.click();p.locator('[data-event-choice="0"]').click();repaired=p.evaluate('__bridgeStates.state()');assert repaired['open'] and repaired['condition']==100 and funded['cash']-repaired['cash']==funded['repair'] and abs(funded['total']-repaired['total'])<.001 and repaired['valid'],repaired
 remove=p.locator('[data-bridge-remove]');remove.scroll_into_view_if_needed();remove.click();p.locator('[data-event-choice="1"]').click();cancelled=p.evaluate('__bridgeStates.state()');assert cancelled['cash']==repaired['cash'] and cancelled['bridges']==1
 remove=p.locator('[data-bridge-remove]');remove.scroll_into_view_if_needed();remove.click();p.locator('[data-event-choice="0"]').click();retired=p.evaluate('__bridgeStates.state()');assert retired['bridges']==0 and retired['cells']==[2]*5 and retired['cash']-repaired['cash']==repaired['quote']['salvage'] and abs(retired['total']-repaired['total'])<.001 and retired['valid'],retired;fishery=p.evaluate('__bridgeStates.fishery()');assert fishery['planningDenied'] and fishery['treasurySufficient'] and fishery['moneyConserved'],fishery;b.close()
print(json.dumps({'source_sha256':hashlib.sha256(source.encode()).hexdigest(),'atomicArchiveFaults':faults,'activeBus':bus,'workingWaterProtection':fishery,'closed':closed,'repairCost':funded['repair'],'salvage':retired['cash']-repaired['cash'],'actualRepairCancelAndDecommissionControls':True},indent=2));print('PASS bridge graph fault rejection, active transit conflict, unfunded closure, paid repair and conserved decommission')
